const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const geometry = ee.Geometry.Point([-118.27, 33.95]); // South Los Angeles, CA
    const band = 'tropospheric_NO2_column_number_density';
    const collectionId = 'COPERNICUS/S5P/OFFL/L3_NO2';

    const periods = {
        '2021': { 'start': '2021-10-01', 'end': '2021-10-23' },
        '2019': { 'start': '2019-10-01', 'end': '2019-10-23' },
        '2018': { 'start': '2018-10-01', 'end': '2018-10-23' }
    };

    // Function to process a collection for a given year
    function getMeanNO2(year) {
        const dateRange = periods[year];
        const collection = ee.ImageCollection(collectionId)
            .filterDate(dateRange.start, dateRange.end)
            .filterBounds(geometry)
            .select([band, 'qa_value']);

        const size = collection.size().getInfo();
        if (size === 0) {
            return { 'mean': null, 'size': 0, 'pixels': null };
        }

        // Mask for high-quality pixels (cloud-free)
        const maskedCollection = collection.map(function(image) {
            const qaMask = image.select('qa_value').gt(0.75);
            return image.select(band).updateMask(qaMask);
        });

        const meanImage = maskedCollection.mean();

        const stats = meanImage.reduceRegion({
            reducer: ee.Reducer.mean().combine({
                reducer2: ee.Reducer.count(),
                sharedInputs: true
            }),
            geometry: geometry,
            scale: 1000,
            maxPixels: 1e9
        });

        const meanVal = stats.get(band).getInfo();
        const pixelCount = stats.get(band + '_count').getInfo();

        return { 'mean': meanVal, 'size': size, 'pixels': pixelCount };
    }

    try {
        const results = {};
        for (const year in periods) {
            results[year] = getMeanNO2(year);
        }

        // --- Validation & Final Answer ---
        // C1: Empty Collection Check
        if (results['2021'].size === 0 || results['2019'].size === 0 || results['2018'].size === 0) {
            console.log(`Image count 2021: ${results['2021'].size}`);
            console.log(`Image count 2019: ${results['2019'].size}`);
            console.log(`Image count 2018: ${results['2018'].size}`);
            console.log("Empty image collection for one or more periods.");
            console.log("C1");
            return;
        }

        // C2: No Valid Pixels Check
        if (results['2021'].pixels === 0 || results['2019'].pixels === 0 || results['2018'].pixels === 0) {
            console.log(`Valid pixels 2021: ${results['2021'].pixels}`);
            console.log(`Valid pixels 2019: ${results['2019'].pixels}`);
            console.log(`Valid pixels 2018: ${results['2018'].pixels}`);
            console.log("No valid pixels found after cloud/quality masking for one or more periods.");
            console.log("C2");
            return;
        }

        // C3: Calculation Failure Check
        if (results['2021'].mean === null || results['2019'].mean === null || results['2018'].mean === null) {
             console.log(`Mean NO2 2021: ${results['2021'].mean}`);
             console.log(`Mean NO2 2019: ${results['2019'].mean}`);
             console.log(`Mean NO2 2018: ${results['2018'].mean}`);
             console.log("Calculation failed, result is null.");
             console.log("C3");
             return;
        }

        const no2_2021 = results['2021'].mean;
        const no2_2019 = results['2019'].mean;
        const no2_2018 = results['2018'].mean;

        // Print evidence (units are mol/m^2)
        console.log(`Mean Tropospheric NO2 (Oct 1-23, 2021): ${no2_2021.toExponential(4)} mol/m^2`);
        console.log(`Mean Tropospheric NO2 (Oct 1-23, 2019): ${no2_2019.toExponential(4)} mol/m^2`);
        console.log(`Mean Tropospheric NO2 (Oct 1-23, 2018): ${no2_2018.toExponential(4)} mol/m^2`);

        if (no2_2021 < no2_2019 && no2_2021 < no2_2018) {
            console.log("A");
        } else {
            console.log("B");
        }

    } catch (e) {
        console.error("An error occurred during analysis: " + e.toString());
        console.log("D");
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
